IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = N'demo_colombia')
    CREATE DATABASE [demo_colombia];
GO
USE [demo_colombia];
GO

IF OBJECT_ID(N'dbo.clientes', N'U') IS NOT NULL DROP TABLE dbo.clientes;
CREATE TABLE dbo.clientes (
    [id] INT,
    [nombre] VARCHAR(100),
    [apellido] VARCHAR(100),
    [email] VARCHAR(150),
    [telefono] VARCHAR(30),
    [cedula_cc] VARCHAR(25),
    [fecha_nacimiento] DATE,
    [genero] VARCHAR(10),
    [estado_civil] VARCHAR(20),
    [direccion_linea1] VARCHAR(200),
    [direccion_linea2] VARCHAR(100),
    [ciudad] VARCHAR(100),
    [departamento] VARCHAR(100),
    [codigo_postal] VARCHAR(15),
    [pais] VARCHAR(50)
);
GO

IF OBJECT_ID(N'dbo.empleados', N'U') IS NOT NULL DROP TABLE dbo.empleados;
CREATE TABLE dbo.empleados (
    [id] INT,
    [nombre] VARCHAR(100),
    [apellido] VARCHAR(100),
    [email_corporativo] VARCHAR(150),
    [email_personal] VARCHAR(150),
    [telefono] VARCHAR(30),
    [cedula_cc] VARCHAR(25),
    [fecha_nacimiento] DATE,
    [cargo] VARCHAR(100),
    [departamento] VARCHAR(100),
    [salario] DECIMAL(12,2),
    [fecha_ingreso] DATE,
    [direccion_linea1] VARCHAR(200),
    [direccion_linea2] VARCHAR(100),
    [ciudad] VARCHAR(100),
    [codigo_postal] VARCHAR(15),
    [banco] VARCHAR(100),
    [cuenta_bancaria] VARCHAR(30)
);
GO

IF OBJECT_ID(N'dbo.cuentas_bancarias', N'U') IS NOT NULL DROP TABLE dbo.cuentas_bancarias;
CREATE TABLE dbo.cuentas_bancarias (
    [id] INT,
    [numero_cuenta] VARCHAR(30),
    [sucursal] VARCHAR(10),
    [tipo_cuenta] VARCHAR(30),
    [saldo] DECIMAL(14,2),
    [limite] DECIMAL(14,2),
    [titular] VARCHAR(200),
    [cedula_cc_titular] VARCHAR(25),
    [banco] VARCHAR(100),
    [fecha_apertura] DATE,
    [estado] VARCHAR(20)
);
GO

IF OBJECT_ID(N'dbo.tarjetas_credito', N'U') IS NOT NULL DROP TABLE dbo.tarjetas_credito;
CREATE TABLE dbo.tarjetas_credito (
    [id] INT,
    [numero_tarjeta] VARCHAR(25),
    [nombre_titular] VARCHAR(200),
    [vencimiento] VARCHAR(8),
    [red] VARCHAR(30),
    [limite] DECIMAL(12,2),
    [factura_actual] DECIMAL(12,2),
    [estado] VARCHAR(20),
    [cedula_cc_titular] VARCHAR(25)
);
GO

IF OBJECT_ID(N'dbo.pedidos', N'U') IS NOT NULL DROP TABLE dbo.pedidos;
CREATE TABLE dbo.pedidos (
    [id] INT,
    [numero_pedido] VARCHAR(20),
    [fecha_pedido] DATE,
    [nombre_cliente] VARCHAR(200),
    [cedula_cc_cliente] VARCHAR(25),
    [monto_total] DECIMAL(12,2),
    [estado] VARCHAR(30),
    [direccion_entrega] VARCHAR(200),
    [complemento_entrega] VARCHAR(100),
    [ciudad_entrega] VARCHAR(100),
    [codigo_postal_entrega] VARCHAR(15)
);
GO

IF OBJECT_ID(N'dbo.historiales_medicos', N'U') IS NOT NULL DROP TABLE dbo.historiales_medicos;
CREATE TABLE dbo.historiales_medicos (
    [id] INT,
    [nombre_paciente] VARCHAR(200),
    [cedula_cc_paciente] VARCHAR(25),
    [fecha_nacimiento] DATE,
    [tipo_sangre] VARCHAR(5),
    [diagnostico] VARCHAR(200),
    [medicamentos] VARCHAR(200),
    [medico_responsable] VARCHAR(200),
    [seguro_medico] VARCHAR(100),
    [fecha_consulta] DATE
);
GO

IF OBJECT_ID(N'dbo.proveedores', N'U') IS NOT NULL DROP TABLE dbo.proveedores;
CREATE TABLE dbo.proveedores (
    [id] INT,
    [nombre_empresa] VARCHAR(200),
    [nit] VARCHAR(25),
    [nombre_contacto] VARCHAR(200),
    [email] VARCHAR(150),
    [telefono] VARCHAR(30),
    [direccion] VARCHAR(200),
    [ciudad] VARCHAR(100),
    [codigo_postal] VARCHAR(15),
    [segmento] VARCHAR(100)
);
GO

IF OBJECT_ID(N'dbo.transacciones', N'U') IS NOT NULL DROP TABLE dbo.transacciones;
CREATE TABLE dbo.transacciones (
    [id] INT,
    [fecha_transaccion] DATETIME2,
    [tipo] VARCHAR(50),
    [monto] DECIMAL(14,2),
    [cuenta_origen] VARCHAR(30),
    [cuenta_destino] VARCHAR(30),
    [descripcion] VARCHAR(200),
    [estado] VARCHAR(30),
    [ip_origen] VARCHAR(50),
    [ubicacion] VARCHAR(100)
);
GO

IF OBJECT_ID(N'dbo.logs_acceso', N'U') IS NOT NULL DROP TABLE dbo.logs_acceso;
CREATE TABLE dbo.logs_acceso (
    [id] INT,
    [fecha_hora] DATETIME2,
    [usuario_id] INT,
    [email_usuario] VARCHAR(150),
    [ip_address] VARCHAR(50),
    [user_agent] VARCHAR(300),
    [accion] VARCHAR(50),
    [recurso] VARCHAR(200),
    [codigo_estado] INT,
    [ubicacion] VARCHAR(100)
);
GO

IF OBJECT_ID(N'dbo.polizas_seguro', N'U') IS NOT NULL DROP TABLE dbo.polizas_seguro;
CREATE TABLE dbo.polizas_seguro (
    [id] INT,
    [numero_poliza] VARCHAR(20),
    [nombre_titular] VARCHAR(200),
    [cedula_cc_titular] VARCHAR(25),
    [fecha_nacimiento] DATE,
    [tipo_seguro] VARCHAR(50),
    [cobertura] DECIMAL(14,2),
    [prima_mensual] DECIMAL(10,2),
    [fecha_inicio] DATE,
    [fecha_fin] DATE,
    [beneficiario] VARCHAR(200)
);
GO

IF OBJECT_ID(N'dbo.contratos', N'U') IS NOT NULL DROP TABLE dbo.contratos;
CREATE TABLE dbo.contratos (
    [id] INT,
    [numero_contrato] VARCHAR(20),
    [nombre_empresa] VARCHAR(200),
    [nit_empresa] VARCHAR(25),
    [nombre_contacto] VARCHAR(200),
    [email_contacto] VARCHAR(150),
    [telefono_contacto] VARCHAR(30),
    [monto_contrato] DECIMAL(16,2),
    [fecha_inicio] DATE,
    [fecha_fin] DATE,
    [estado] VARCHAR(20)
);
GO

IF OBJECT_ID(N'dbo.leads_marketing', N'U') IS NOT NULL DROP TABLE dbo.leads_marketing;
CREATE TABLE dbo.leads_marketing (
    [id] INT,
    [nombre] VARCHAR(100),
    [apellido] VARCHAR(100),
    [email] VARCHAR(150),
    [telefono] VARCHAR(30),
    [empresa] VARCHAR(200),
    [cargo] VARCHAR(100),
    [fuente] VARCHAR(50),
    [fecha_registro] DATE,
    [estado] VARCHAR(30),
    [interes] VARCHAR(100)
);
GO

